<?php declare(strict_types=1); $d=$record??$old??[]; ?><div class="card"><div class="form-grid"><div class="form-group full"><label>Title *</label><input name="title" required value="<?=htmlspecialchars((string)($d['title']??''))?>"></div><div class="form-group"><label>Destination</label><select name="destination_id"><option value="">—</option><?php foreach($destinations as $x): ?><option value="<?=$x['id']?>" <?=((string)($d['destination_id']??''))===(string)$x['id']?'selected':''?>><?=htmlspecialchars($x['name'].' · '.$x['district'])?></option><?php endforeach; ?></select></div><div class="form-group"><label>Provider</label><select name="provider_id"><option value="">Independent</option><?php foreach($providers as $x): ?><option value="<?=$x['id']?>" <?=((string)($d['provider_id']??''))===(string)$x['id']?'selected':''?>><?=htmlspecialchars($x['legal_name'])?></option><?php endforeach; ?></select></div><div class="form-group"><label>Type</label><input name="experience_type" value="<?=htmlspecialchars((string)($d['experience_type']??''))?>"></div><div class="form-group"><label>Duration (minutes)</label><input type="number" min="1" name="duration_minutes" value="<?=htmlspecialchars((string)($d['duration_minutes']??''))?>"></div><div class="form-group"><label>Price (₹)</label><input type="number" min="0" step="0.01" name="price" value="<?=htmlspecialchars((string)($d['price']??''))?>"></div><div class="form-group"><label>Max participants</label><input type="number" min="1" name="max_participants" value="<?=htmlspecialchars((string)($d['max_participants']??''))?>"></div><div class="form-group"><label>Meeting point</label><input name="meeting_point" value="<?=htmlspecialchars((string)($d['meeting_point']??''))?>"></div><div class="form-group full"><label>Description</label><textarea name="description" rows="5"><?=htmlspecialchars((string)($d['description']??''))?></textarea></div><div class="form-group"><label>Included</label><textarea name="included" rows="3"><?=htmlspecialchars((string)($d['included']??''))?></textarea></div><div class="form-group"><label>Requirements</label><textarea name="requirements" rows="3"><?=htmlspecialchars((string)($d['requirements']??''))?></textarea></div><div class="form-group"><label>Latitude</label><input name="latitude" value="<?=htmlspecialchars((string)($d['latitude']??''))?>"></div><div class="form-group"><label>Longitude</label><input name="longitude" value="<?=htmlspecialchars((string)($d['longitude']??''))?>"></div><div class="form-group"><label>Status</label><select name="status"><?php foreach(['Draft','Pending','Active','Inactive','Suspended'] as $v): ?><option value="<?=$v?>" <?=($d['status']??'Draft')===$v?'selected':''?>><?=$v?></option><?php endforeach; ?></select></div><div class="form-group"><label><input type="checkbox" name="featured" value="1" <?=!empty($d['featured'])?'checked':''?>> Featured</label></div></div></div><style>.form-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:16px}.full{grid-column:1/-1}.form-group label{display:block;font-weight:600;margin-bottom:6px}.form-group input,.form-group select,.form-group textarea{width:100%;box-sizing:border-box}@media(max-width:700px){.form-grid{grid-template-columns:1fr}.full{grid-column:auto}}</style>
